import pandas as pd
import os

csv_files = [f"experiment_{i}_csv" for i in range(1, 12)]
all_dfs = {}
for i, fname in enumerate(csv_files, 1):
    try:
        path = eval(fname)
        df = pd.read_csv(path)
        all_dfs[i] = df
        print(f"\n=== Experiment {i} ===")
        print(f"Shape: {df.shape}")
        print(f"Columns: {list(df.columns)}")
        if len(df) > 0:
            print(df.head(3))
    except Exception as e:
        print(f"Experiment {i}: {e}")

# Now let's find the union of all columns
all_cols = set()
for df in all_dfs.values():
    all_cols.update(df.columns)
print(f"\n\n=== ALL AVAILABLE COLUMNS ===")
for c in sorted(all_cols):
    print(f"  {c}")
